using System;using System.Drawing;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Windows.Forms;
namespace ServiceTool{static class ProgressUiPolishTests{
static int count;static void Check(bool ok,string text){count++;if(!ok)throw new Exception(text);}
static IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}
static void Pump(){for(int i=0;i<15;i++)Application.DoEvents();}
[STAThread]static int Main(){try{foreach(bool dark in new[]{false,true})foreach(float scale in new[]{1F,1.25F,1.5F,2F}){
var palette=ThemePalette.Create(dark);
using(var logs=new LogArchiveDialog(palette,"DK.License.Server.Host",Enumerable.Range(0,18).Select(i=>new LogDateFolder{Name=DateTime.Today.AddDays(-i).ToString("yyyy.MM.dd"),Date=DateTime.Today.AddDays(-i)}).ToList(),DateTime.Today)){
logs.Show();if(scale!=1)logs.Scale(new SizeF(scale,scale));Pump();var all=Walk(logs).ToArray();var dates=all.OfType<LogDateCheckBox>().ToArray();Check(dates.All(c=>c.BackColor==palette.Canvas&&c.Parent.BackColor==palette.Canvas),"Date background is Canvas in both themes");
var save=(Button)logs.AcceptButton;var cancel=(Button)logs.CancelButton;Check(Math.Abs(save.Width-cancel.Width)<=1&&save.Height==cancel.Height,"Equal log footer actions");Check(save.PointToScreen(Point.Empty).X-cancel.PointToScreen(new Point(cancel.Width,0)).X>=11*scale,"Log footer has 12px gap");
foreach(var button in new[]{save,cancel})Check(button.Parent.ClientRectangle.Contains(button.Bounds),"Footer actions fit");
var combo=all.OfType<BrandComboBox>().Single();Check(!combo.HoverHighlight&&combo.FlatStyle==FlatStyle.Flat,"Logs use shared monolithic combo");
combo.SelectedIndex=1;dates=Walk(logs).OfType<LogDateCheckBox>().ToArray();dates[0].Checked=true;Check(dates[0].Checked,"Date selection still works");logs.Close();}
using(var library=new LibraryManagerForm(true)){library.SetTheme(dark,false);library.Show();if(scale!=1)library.Scale(new SizeF(scale,scale));Pump();var button=(Button)typeof(LibraryManagerForm).GetField("install",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(library);button.Text="Действия с выбранными";var required=TextRenderer.MeasureText(button.Text,button.Font,new Size(Math.Max(1,button.Width-16),Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix);Check(required.Height<=button.Height-6,"Library action label fits full height");Check(button.Width>TextRenderer.MeasureText("выбранными",button.Font).Width+16,"Longest word fits without clipping");library.Close();}
}
foreach(bool dark in new[]{false,true})using(var account=new ServiceAccountDialog(ThemePalette.Create(dark),ServiceInstallProfile.Default(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"fixture.exe")),false)){
account.Show();Pump();foreach(var combo in Walk(account).OfType<BrandComboBox>()){Check(!combo.HoverHighlight&&combo.FlatStyle==FlatStyle.Flat,"All account combos use shared chrome");using(var bitmap=new Bitmap(combo.Width,combo.Height)){combo.DrawToBitmap(bitmap,combo.ClientRectangle);Check(bitmap.GetPixel(0,combo.Height/2).ToArgb()==ThemePalette.Create(dark).Border.ToArgb(),"Account combo edge uses palette border");}}account.Close();}
foreach(bool dark in new[]{false,true})using(var host=new Form{ClientSize=new Size(460,120),BackColor=ThemePalette.Create(dark).Canvas})using(var view=new DownloadProgressView{Dock=DockStyle.Fill,Palette=ThemePalette.Create(dark),Font=new Font("Segoe UI",10)}){
host.Controls.Add(view);view.Report(new TransferProgress{Stage="Одинаковый текст",WorkText="Одинаковый текст",Active=false});host.Show();Pump();using(var bitmap=new Bitmap(view.Width,view.Height)){view.DrawToBitmap(bitmap,view.ClientRectangle);float dpi;using(var graphics=view.CreateGraphics())dpi=graphics.DpiX/96F;int line=Math.Max(view.Font.Height,(int)Math.Round(18*dpi)),lower=line+2*(int)Math.Round(10*dpi)+(int)Math.Round(22*dpi);bool equal=true;for(int y=0;y<line;y++)for(int x=0;x<200;x++)if(bitmap.GetPixel(x,y)!=bitmap.GetPixel(x,y+lower))equal=false;Check(equal,"Upper/lower progress text have identical contrast and ink layout");bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"progress-contrast-"+dark+".png"));}host.Close();}
Console.WriteLine("PASS: "+count+" UI polish checks: progress contrast, log Canvas/equal buttons/gaps/date selection, shared combos, library caption; both themes/100–200%. No system changes.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}}